PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ex: <http://example.org/>
SELECT  * {
  ?bind rdfs:label ?b1 ;
        a ex:Unit .
  FILTER (?b1 = 'Unit2') .
  BIND(?bind AS ?n0)
  ?n0 ex:has ?n1 
 }

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX ex: <http://example.org/>
SELECT *
    WHERE {
            BIND ( ex:a AS ?a )
            BIND ( ex:b AS ?b )
            ?a ex:p* ?c .
            FILTER EXISTS { ?c rdf:type ex:T }
            FILTER NOT EXISTS { ?c ex:q ?d}
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX ex: <http://example.org/>
SELECT *
    WHERE {
            FILTER EXISTS { ?c rdf:type ex:T }
            FILTER NOT EXISTS { ?c ex:q ?d }
            BIND ( ex:a AS ?a )
            BIND ( ex:b AS ?b )
            ?a ex:p* ?c .
}

